# -*- coding: utf-8 -*-
"""
地理识图题库 - 基于18张湘教版地理填充图题
图片路径: /shitu_images/1.png ~ 18.png
"""

from typing import List, Dict


def _make_question(
    q_id: str,
    question: str,
    options: List[str],
    answer: int,
    explanation: str,
    image: str,
    difficulty: str = "medium",
    topic: str = "地理识图"
) -> Dict:
    """构造标准识图题目"""
    return {
        "id": q_id,
        "type": "select",
        "question": question,
        "options": options,
        "answer": answer,
        "explanation": explanation,
        "image": image,
        "difficulty": difficulty,
        "topic": topic,
    }


